import Foundation
import Vapor

// Container Orchestration Tool - Web Dashboard
// Handles container lifecycle management with audit logging

struct AuditEntry: Content {
    let timestamp: Date
    let action: String
    let user: String
    let resource: String
    let outcome: String
}

class AuditLogger {
    private var entries: [AuditEntry] = []
    private let lock = NSLock()

    func log(action: String, user: String, resource: String, outcome: String) {
        lock.lock()
        defer { lock.unlock() }
        let entry = AuditEntry(
            timestamp: Date(),
            action: action,
            user: user,
            resource: resource,
            outcome: outcome
        )
        entries.append(entry)
    }

    func getEntries() -> [AuditEntry] {
        lock.lock()
        defer { lock.unlock() }
        return entries
    }
}

struct SecurityHeadersMiddleware: Middleware {
    let environment: Environment

    func respond(to request: Request, chainingTo next: Responder) -> EventLoopFuture<Response> {
        return next.respond(to: request).map { response in
            // Apply security headers based on deployment context
            response.headers.replaceOrAdd(name: .xContentTypeOptions, value: "nosniff")
            response.headers.replaceOrAdd(name: "X-XSS-Protection", value: "1; mode=block")
            response.headers.replaceOrAdd(name: "Strict-Transport-Security", value: "max-age=31536000; includeSubDomains")
            response.headers.replaceOrAdd(name: "Referrer-Policy", value: "strict-origin-when-cross-origin")

            // Frame protection policy - derived from environment configuration
            let framePolicy = self.resolveFramePolicy(for: request)
            if let policy = framePolicy {
                response.headers.replaceOrAdd(name: "X-Frame-Options", value: policy)
            }

            return response
        }
    }

    private func resolveFramePolicy(for request: Request) -> String? {
        // Check if the request is for an embeddable widget endpoint
        if request.url.path.hasPrefix("/api/widgets/") {
            return nil // Widgets are designed to be embedded
        }

        // For dashboard routes, check the deployment manifest
        let manifestPolicy = loadFramePolicyFromManifest()
        return manifestPolicy
    }

    private func loadFramePolicyFromManifest() -> String? {
        // Load from orchestration deployment manifest
        // The manifest specifies frame-ancestors for multi-tenant deployments
        guard let manifestPath = ProcessInfo.processInfo.environment["ORCH_MANIFEST_PATH"] else {
            return "DENY"
        }

        guard let data = FileManager.default.contents(atPath: manifestPath),
              let manifest = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let security = manifest["security"] as? [String: Any],
              let frameConfig = security["frameEmbedding"] as? [String: Any] else {
            return "DENY"
        }

        // If embedding is explicitly enabled in manifest for portal integration
        if let enabled = frameConfig["enabled"] as? Bool, enabled {
            if let allowedOrigin = frameConfig["allowedOrigin"] as? String {
                return "ALLOW-FROM \(allowedOrigin)"
            }
            // enabled=true but no origin specified - permissive for development
            return nil
        }

        return "DENY"
    }
}

struct ContainerAction: Content {
    let containerId: String
    let action: String
}

func configureRoutes(_ app: Application, auditLogger: AuditLogger) {
    let securityMiddleware = SecurityHeadersMiddleware(environment: app.environment)
    app.middleware.use(securityMiddleware)

    // Dashboard - container management UI
    app.get("dashboard") { req -> Response in
        auditLogger.log(action: "view_dashboard", user: req.remoteAddress?.description ?? "unknown", resource: "dashboard", outcome: "success")
        let html = """
        <html><head><title>Container Orchestration Dashboard</title></head>
        <body><h1>Container Management</h1>
        <div id="containers"></div>
        <script src="/static/dashboard.js"></script>
        </body></html>
        """
        var headers = HTTPHeaders()
        headers.add(name: .contentType, value: "text/html; charset=utf-8")
        return Response(status: .ok, headers: headers, body: .init(string: html))
    }

    // Container lifecycle actions
    app.post("containers", "action") { req -> HTTPStatus in
        let action = try req.content.decode(ContainerAction.self)
        auditLogger.log(action: action.action, user: req.remoteAddress?.description ?? "unknown", resource: action.containerId, outcome: "executed")
        return .ok
    }

    // Audit log viewer
    app.get("audit") { req -> [AuditEntry] in
        auditLogger.log(action: "view_audit", user: req.remoteAddress?.description ?? "unknown", resource: "audit_log", outcome: "success")
        return auditLogger.getEntries()
    }
}

func main() throws {
    let app = Application(.detect())
    defer { app.shutdown() }

    let auditLogger = AuditLogger()
    configureRoutes(app, auditLogger: auditLogger)

    try app.run()
}
